// generator.mjs — the d-frame H¹-generator D_μ at a non-Scott-continuous firing.
//
// (After the corpus theorem `d-frame-h1-generator-at-nsc-firing.md`, status: proved.)
//
// `obstruction` shows that H¹ is generated by the firings at LIMIT (non-Scott-continuous) stages. This
// module gives each such firing its d-frame structure: at firing μ, exactly one cell is newly designated,
// and its bilattice value fixes a generator
//
//   D_μ = (L₊, L₋, con, tot) ∈ dFrm
//
//   truth-only (t):  (ℤ, 0, trivial,                    trivial)
//   falsity-only (f):(0, ℤ, trivial,                    trivial)
//   ⊤-firing:        (ℤ, ℤ, con-fails-on-singleton-pair, trivial)
//   ⊥-firing:        (0, 0, trivial,                    trivial)   — no evidence content
//
// The d-frame cohomology is the direct sum H¹_dFrm = ⊕_μ D_μ over the firings. Its abelian SHADOW
// S(⊕ D_μ) = (ℤ^{#truth+⊤}, ℤ^{#falsity+⊤}) recovers the two `dframe`-module rank counts — but the
// d-frame keeps the per-firing consistency/totality the shadow throws away (notably the ⊤-firing's
// con-failure, recording it as a paraconsistent witness). This generalizes the `dframe` module from
// substitution settlings (per-letter) to ANY settling (per-firing), tying it to `obstruction`'s firings.

import { SIDE_CONTRIBUTION, classifyFiring } from "@lenticule-science/metrologic/dframe/cohomology";
import { GAUGE } from "@lenticule-science/metrologic/verdier/gauge";
import { nscFirings } from "@lenticule-science/metrologic/obstruction/settling";

/**
 * The d-frame generator D_μ for a firing of a given bilattice value.
 * @param {"t"|"f"|"top"|"bot"} value @returns {{ value, firingType, lPlus, lMinus, consistency, totality }}
 */
export function dframeGenerator(value) {
  const side = SIDE_CONTRIBUTION[value];
  if (!side) throw new RangeError(`not a bilattice value: ${value}`);
  const [plus, minus] = side;
  return {
    value,
    firingType: classifyFiring(value),
    lPlus: plus ? 1 : 0,
    lMinus: minus ? 1 : 0,
    consistency: plus && minus ? "con-fails-on-singleton-pair" : "trivial",
    totality: "trivial",
  };
}

/**
 * The d-frame H¹ of a settling, as the direct sum ⊕_μ D_μ over its valued firings. Each valued firing is
 * `{ stage, value }` (one firing cell per NSC firing, carrying its bilattice value).
 * @param {{stage:number, value:string}[]} valuedFirings
 * @returns {{ generators: object[], rank: number, lPlus: number, lMinus: number, structure: string }}
 */
export function h1Dframe(valuedFirings) {
  const generators = valuedFirings.map((f) => ({ stage: f.stage, value: f.value, D: dframeGenerator(f.value) }));
  const lPlus = generators.filter((g) => g.D.lPlus).length;  // truth-only + ⊤
  const lMinus = generators.filter((g) => g.D.lMinus).length; // falsity-only + ⊤
  const structure = generators.length ? generators.map((g) => `D_${g.stage}`).join(" ⊕ ") : "0";
  return { generators, rank: generators.length, lPlus, lMinus, structure };
}

/**
 * The shadow projection S(⊕ D_μ) = (ℤ^{#truth+⊤}, ℤ^{#falsity+⊤}) — the abelian content the `dframe`
 * module's bigraded shadow also computes.
 * @param {{stage:number, value:string}[]} valuedFirings
 */
export function shadow(valuedFirings) {
  const h = h1Dframe(valuedFirings);
  return { lPlus: h.lPlus, lMinus: h.lMinus, truthSide: `Z^${h.lPlus}`, falsitySide: `Z^${h.lMinus}` };
}

/**
 * The value-category swap on a generator (bilattice negation D_val): truth-only ↔ falsity-only, ⊤ and ⊥
 * fixed. The unconditional firing-orbit-type rule the strong-MLD classification uses.
 * @param {{value:string}} D @returns {object}
 */
export const negateGenerator = (D) => dframeGenerator(GAUGE.negation[D.value]);

/**
 * Linear independence of the generator family {D_μ}: the generators are independent iff their firings sit
 * at distinct stages (newly-addedness at each μ — no earlier-stage cochain produces D_μ). So the rank of
 * H¹_dFrm equals the number of firings.
 * @param {{stage:number, value:string}[]} valuedFirings @returns {boolean}
 */
export function linearlyIndependent(valuedFirings) {
  const stages = valuedFirings.map((f) => f.stage);
  return new Set(stages).size === stages.length;
}

/**
 * Build the valued firings of an `obstruction` settling: zip its non-Scott-continuous (limit) firings
 * with a list of bilattice values (one per firing, in firing order).
 * @param {object} settling an obstruction settling @param {string[]} values
 * @returns {{stage:number, value:string}[]}
 */
export function fromSettling(settling, values) {
  const firings = nscFirings(settling);
  if (values.length !== firings.length) {
    throw new RangeError(`expected ${firings.length} values (one per NSC firing), got ${values.length}`);
  }
  return firings.map((f, i) => ({ stage: f.stage, value: values[i] }));
}
